WITH base AS (SELECT * FROM store_sales WHERE store_id IN (2, 4, 5)), summary AS (SELECT CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END sale_cohort, product_id, MAX(sale_date) last_sale_date, SUM(units) total_units FROM base GROUP BY CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END, product_id) SELECT sale_cohort, product_id, last_sale_date, total_units FROM summary WHERE total_units < 70
